#!/usr/bin/env bash
# Проверка правила глушения `notifier_mute_decide` (тред 073, постановка curator
# 2026-09-02: «повторный отказ ОДНОГО и того же уведомителя не должен рождать
# письмо каждый раз»).
#
# Фикстура — каталог `messages/` треда-приёмника с письмами того вида, который
# кладёт сам смотритель: имя файла несёт время, тело — строку-ключ. Проверяется
# ровно то, что стоило девяти писем за тринадцать минут: ДВА ОДИНАКОВЫХ ОТКАЗА
# ПОДРЯД дают одно письмо, а не два.
#
# Прогон руками: bash .github/scripts/notifier-mute.test.sh
# В сьюте он же поднимается процессом (`src/roles/notifier-mute.process.test.ts`)
# — в отличие от `comms-push.test.sh`, оставленного ручным: там правило гоняется
# при правке файла, а здесь правило решает, поедет ли письмо, и молчаливо
# сломанное оно неотличимо от исправного.
set -uo pipefail

cd "$(dirname "$0")"
# shellcheck source=./notifier-mute.sh
source ./notifier-mute.sh

FAILED=0
check() { # <что> <ожидалось> <получено>
  if [ "$2" = "$3" ]; then
    echo "ok   · $1"
  else
    echo "FAIL · $1: ожидалось '$2', получено '$3'"
    FAILED=1
  fi
}

DIR="$(mktemp -d)"
trap 'rm -rf "$DIR"' EXIT
MESSAGES="$DIR/messages"
mkdir -p "$MESSAGES"

letter() { # <метка в имени файла> <имя уведомителя>
  {
    printf '🔕 **Уведомитель `%s` отказал: `failure`.**\n\n' "$2"
    printf '%s · окно %s с\n' "$(notifier_mute_marker "$2")" "$NOTIFIER_MUTE_WINDOW_SEC"
  } > "$MESSAGES/$1-github.md"
}

# 1. Первый отказ — писать всегда: тред о нём ещё ничего не знает.
check "письма об уведомителе нет — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:39:00Z')"

# 2. ВТОРОЙ ОДИНАКОВЫЙ ОТКАЗ ПОДРЯД — тот самый случай петли: письмо уже лежит,
#    прошло полминуты. Ожидается глушение с названным возрастом.
letter '2026-09-02T16-39-00Z' 'Comms Derived'
check "повтор через 30 с — заглушён" \
  "mute 2026-09-02T16:39:00Z 30" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:39:30Z')"

# 3. Окно кончилось — письмо снова едет, и метка прошлого письма отдаётся
#    наружу: ею считается число заглушённых для громкой строки.
check "через 15 мин 1 с — письмо едет" \
  "deliver 2026-09-02T16:39:00Z 901" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:54:01Z')"
check "ровно на границе окна — письмо едет" \
  "deliver 2026-09-02T16:39:00Z 900" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:54:00Z')"

# 4. ДРУГОЙ уведомитель молчанием соседа не глушится: ключ — имя, и он различает.
check "другой уведомитель в том же окне — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$MESSAGES" 'Merge Notify' '2026-09-02T16:39:30Z')"

# 5. Из двух писем берётся ПОСЛЕДНЕЕ, а не первое попавшееся: серия в треде
#    длиннее одного письма, и решать по старшему значило бы разглушиться зря.
letter '2026-09-02T16-52-25Z' 'Comms Derived'
check "решает последнее письмо, а не первое" \
  "mute 2026-09-02T16:52:25Z 34" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:52:59Z')"

# 6. Отказ читается в сторону письма, а не тишины.
check "письмо из будущего (часы разъехались) — письмо едет" \
  "deliver 2026-09-02T16:52:25Z -145" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:50:00Z')"
check "пустой каталог — письмо едет" \
  "deliver - -" "$(notifier_mute_decide "$DIR/нет-такого" 'Comms Derived' '2026-09-02T16:39:30Z')"

# 7. Окно — параметр правила, а не константа внутри него: письмо той же
#    давности при коротком окне уже не глушится.
check "окно передано явно — правило считает по нему" \
  "deliver 2026-09-02T16:52:25Z 34" "$(notifier_mute_decide "$MESSAGES" 'Comms Derived' '2026-09-02T16:52:59Z' 10)"

# 8. ВЫБОР ЛЕНТЫ У СТОЯЧЕГО АДРЕСА (тред 080). Приёмник — не литерал: адрес
#    исполняют обычные треды по очереди, и правило обязано читать ленту того,
#    кто играет его СЕЙЧАС, иначе оно заглушит звонок серией из закрытого.
MAIL="$DIR/mail"
mkdir -p "$MAIL"
receiver() { # <id треда> <status>
  mkdir -p "$MAIL/$1/messages"
  printf -- '---\ntitle: Стоячий адрес\nparticipants: github, dev-core\nstatus: %s\n---\n' "$2" \
    > "$MAIL/$1/_meta.md"
}

check "приёмника у адреса нет вовсе — ленты нет, письмо поедет и откроет его" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

receiver '077-notifier-down' open
check "единственный открытый приёмник — его лента" \
  "$MAIL/077-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# Старший по номеру, а не первый попавшийся: адрес переезжает вперёд.
receiver '104-notifier-down' open
check "открытых несколько — старший по номеру" \
  "$MAIL/104-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# ЗАКРЫТЫЙ ПРИЁМНИК ЛЕНТЫ НЕ ОТДАЁТ — ровно тот случай, ради которого функция и
# написана: письмо поедет в новый приёмник, а серия закрытого заглушила бы его.
receiver '104-notifier-down' closed
check "старший закрыт — читается открытый, что ниже номером" \
  "$MAIL/077-notifier-down/messages" "$(notifier_mute_source "$MAIL" 'notifier-down')"

receiver '077-notifier-down' closed
check "все приёмники закрыты — ленты нет, звонок не глушится" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# Чужой адрес соседним слагом не отвечает: слаг — это и есть имя адреса.
receiver '076-main-red-alarm' open
check "слаг различает адреса" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"
check "слаг соседнего адреса отдаёт свою ленту" \
  "$MAIL/076-main-red-alarm/messages" "$(notifier_mute_source "$MAIL" 'main-red-alarm')"

# Тред без `_meta.md` не кандидат — по той же причине, по которой его пропускает
# дверь: ленту, которую некому прочитать, судить нечем.
mkdir -p "$MAIL/091-notifier-down/messages"
check "приёмник без _meta.md пропускается" \
  "" "$(notifier_mute_source "$MAIL" 'notifier-down')"

# 9. СТЫК ДВУХ ПРАВИЛ: лента выбранного приёмника — это то, по чему решает
#    глушение. Проверяется вместе, потому что порознь обе половины зелены и в
#    том случае, когда воркфлоу читает не тот тред.
receiver '108-notifier-down' open
{
  printf '🔕 **Уведомитель `%s` отказал: `failure`.**\n\n' 'Comms Derived'
  printf '%s · окно %s с\n' "$(notifier_mute_marker 'Comms Derived')" "$NOTIFIER_MUTE_WINDOW_SEC"
} > "$MAIL/108-notifier-down/messages/2026-09-03T16-39-00Z-github.md"
check "решение принимается по ленте выбранного приёмника" \
  "mute 2026-09-03T16:39:00Z 30" \
  "$(notifier_mute_decide "$(notifier_mute_source "$MAIL" 'notifier-down')" 'Comms Derived' '2026-09-03T16:39:30Z')"
# --- 10. ПРЕДИКАТ ГРОМКОСТИ: какие прогоны заглушены (тред 119) ---------------
#
# Первоисточник: письмо смотрителя от 2026-09-03T17:59:23Z (прогон 33787757989)
# напечатало «НЕ ПРОЧИТАНО: GitHub API отказал», а в его же логе стояло
# `expected an object but got: array` — фильтр был тип-ошибочен ПРИ ЛЮБЫХ
# данных, то есть ветвь счёта не могла дать число никогда. Живого отказа для
# проверки не нужно: предикат кормится сохранённым ответом API.
RUNS_JSON="$DIR/runs.json"
cat > "$RUNS_JSON" <<'JSON'
{ "total_count": 11,
  "workflow_runs": [
    { "id": 33787502420, "created_at": "2026-09-03T17:59:00Z", "conclusion": "failure" },
    { "id": 33787757989, "created_at": "2026-09-03T17:59:23Z", "conclusion": "failure" },
    { "id": 33780000001, "created_at": "2026-09-03T15:00:00Z", "conclusion": "success" },
    { "id": 33780000002, "created_at": "2026-09-03T14:00:00Z", "conclusion": "timed_out" },
    { "id": 33770000003, "created_at": "2026-09-03T12:00:00Z", "conclusion": "failure" },
    { "id": 33780000004, "created_at": "2026-09-03T16:00:00Z", "conclusion": "cancelled" },
    { "id": 33780000005, "created_at": "2026-09-03T16:05:00Z", "conclusion": "skipped" },
    { "id": 33780000006, "created_at": "2026-09-03T16:10:00Z", "conclusion": null },
    { "id": 33780000007, "created_at": "2026-09-03T16:15:00Z", "conclusion": "startup_failure" },
    { "id": 33780000008, "created_at": "2026-09-03T16:20:00Z", "conclusion": "action_required" },
    { "id": 33780000009, "created_at": "2026-09-03T16:25:00Z", "conclusion": "stale" }
  ] }
JSON

# (а) отказные позже прошлого письма — их id, и (г) смесь заключений отбирается
#     правильно и НЕ РОНЯЕТ фильтр: `success`, `cancelled`, `skipped` и `null`
#     молча отсеиваются, а не дают тип-ошибку.
check "отказные позже прошлого письма — их id, смесь заключений не роняет фильтр" \
  "33787502420 33780000002 33780000007 33780000008 33780000009" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989)"
# (в) СВОЙ прогон в выдачу не попадает: он создан позже прошлого письма и
#     завершится отказом, но письмо о нём как раз и едет — заглушённым он не был.
check "свой прогон в выдачу не попадает" "нет" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 | grep -qF 33787757989 && echo да || echo нет)"
check "прогон старше прошлого письма не считается заглушённым" "нет" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989 | grep -qF 33770000003 && echo да || echo нет)"
# (б) отказных нет — ПУСТОЙ список и код 0, а не отказ: «заглушать было нечего»
#     это исход, а не ошибка.
check "отказных нет — пустой список" "" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989)"
check "отказных нет — код 0, а не отказ" "0" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989 >/dev/null; echo $?)"
check "все отказные — это свой прогон и старьё, ответ пуст" "" \
  "$(notifier_mute_muted_ids "$RUNS_JSON" '2026-09-03T17:30:00Z' 33787502420 | sed 's/33787757989//;s/^ *//;s/ *$//')"
# Мусор вместо ответа — отказ предиката, и ветвь обязана его увидеть кодом.
printf 'не json\n' > "$DIR/broken.json"
check "ответ не разобрался — ненулевой код" "нет" \
  "$(notifier_mute_muted_ids "$DIR/broken.json" '2026-09-03T13:39:47Z' 1 >/dev/null 2>&1 && echo да || echo нет)"

# --- 11. ТРИ ИСХОДА ВЕТВИ ГРОМКОСТИ — сверяется ТЕКСТ, а не код выхода --------
#
# Дефект треда 119 был ТЕКСТОВЫМ: достижимой оставалась одна ветвь из трёх, и
# она называла виноватым GitHub. Поэтому проверяется строка, которую читатель
# треда увидит. Тело вырезается из `notifier-watch.yml` по маркерам — судится
# файл, который едет, а не его пересказ; формулировки обязаны жить в `.yml`
# (см. комментарий там: `.github/scripts/**` не покрыт `powerDocuments`).
WATCH_YML=../workflows/notifier-watch.yml
BLOCK="$DIR/muted-line.sh"
sed -n '/# >>> notifier-mute: громкость >>>/,/# <<< notifier-mute: громкость <<</p' "$WATCH_YML" \
  | sed '1d;$d' | sed 's/^          //' > "$BLOCK"
check "тело ветви вырезано из notifier-watch.yml по маркерам" "да" \
  "$(grep -q 'MUTED_LINE=' "$BLOCK" && grep -q 'notifier_mute_muted_ids' "$BLOCK" && echo да || echo нет)"

muted_line() { # <ok|fail — исход gh> <файл-ответ> <LAST_AT> <RUN_ID>
  (
    set -euo pipefail
    GH_OUTCOME="$1"
    GH_BODY="$2"
    LAST_AT="$3"
    RUN_ID="$4"
    # Окружение шага — подложное: харнесс задаёт его сам, поэтому имена
    # переменных `env:` воркфлоу сверяются отдельно (раздел 12 ниже).
    GITHUB_REPOSITORY='lle/agent-crew-orchestrator'
    GITHUB_SERVER_URL='https://github.com'
    GITHUB_RUN_ID=33787757989
    WF_NAME='Claude PR Review'
    WF_ID=178000000
    gh() { [ "$GH_OUTCOME" = ok ] || return 1; cat "$GH_BODY"; }
    # shellcheck source=/dev/null
    source "$BLOCK"
    printf '%s' "$MUTED_LINE"
  )
}

check "исход 1 — число со списком прогонов" \
  '🔇 **Заглушено с прошлого письма (`2026-09-03T13:39:47Z`) отказов того же уведомителя: 5** — прогоны 33787502420, 33780000002, 33780000007, 33780000008, 33780000009. Правило — окно 900 с по имени уведомителя (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989)"
check "исход 2 — заглушать было нечего" \
  '🔇 С прошлого письма (`2026-09-03T18:00:00Z`) других отказов этого уведомителя не было — заглушать было нечего.' \
  "$(muted_line ok "$RUNS_JSON" '2026-09-03T18:00:00Z' 33787757989)"
# ИСХОД 3, СТОРОНА ЗАПРОСА: GitHub тут действительно ни при чём как ПРИЧИНА,
# названная наугад, — назван отказ запроса, и читатель послан в лог смотрителя.
check "исход 3а — запрос не выполнен, и это сказано отдельно от разбора" \
  '🔇 Сколько отказов этого уведомителя заглушено с прошлого письма (`2026-09-03T13:39:47Z`) — НЕ ПРОЧИТАНО: список прогонов не получен — запрос к GitHub не выполнен. Само письмо это не задержало. Настоящая ошибка напечатана в логе ЭТОГО прогона смотрителя — https://github.com/lle/agent-crew-orchestrator/actions/runs/33787757989, шаг «Позвонить в тред-приёмник»; в прогонах `Claude PR Review` её нет.' \
  "$(muted_line fail "$RUNS_JSON" '2026-09-03T13:39:47Z' 33787757989)"
# ИСХОД 3б — РОВНО ТОТ ЖИВОЙ СЛУЧАЙ: запрос прошёл, сломан разбор. Прежняя ветвь
# печатала здесь «GitHub API отказал» и посылала читателя в исправную сторону.
BRANCH_ERR="$DIR/branch.err"
check "исход 3б — ответ получен, но не разобран: виноватым GitHub не назван" \
  '🔇 Сколько отказов этого уведомителя заглушено с прошлого письма (`2026-09-03T13:39:47Z`) — НЕ ПРОЧИТАНО: список прогонов получен, но не разобран — отказал отбор отказных прогонов. Само письмо это не задержало. Настоящая ошибка напечатана в логе ЭТОГО прогона смотрителя — https://github.com/lle/agent-crew-orchestrator/actions/runs/33787757989, шаг «Позвонить в тред-приёмник»; в прогонах `Claude PR Review` её нет.' \
  "$(muted_line ok "$DIR/broken.json" '2026-09-03T13:39:47Z' 33787757989 2>"$BRANCH_ERR")"
# Обещание строки проверяется, а не декларируется: раз письмо посылает читателя
# в лог прогона смотрителя, ошибка обязана там БЫТЬ. Именно она и уехала бы в
# `/dev/null`, останься фильтр внутри `gh --jq`.
check "и настоящая ошибка правда напечатана в лог прогона" "да" \
  "$([ -s "$BRANCH_ERR" ] && echo да || echo нет)"
check "прошлого письма нет — строки громкости нет вовсе" "" \
  "$(muted_line ok "$RUNS_JSON" - 33787757989)"

# --- 12. Переменные окружения ветви объявлены шагом ---------------------------
#
# Подложное окружение раздела 11 задаёт харнесс, а не воркфлоу: опечатка в `env:`
# шага так не ловится. Поэтому имена, которые тело берёт снаружи, сверяются с
# файлом отдельно. `GITHUB_*` даёт Actions сам и в `env:` их не объявляют.
for VAR in WF_NAME WF_ID RUN_ID; do
  check "ветвь берёт ${VAR}, и шаг его объявляет" "да" \
    "$(grep -q "^          ${VAR}: " "$WATCH_YML" && echo да || echo нет)"
done

# --- 13. СТЫК АДРЕСА И ГРОМКОСТИ: метку даёт лента приёмника (тред 080), по ---
#     ней считает ветвь громкости (тред 119)
#
# Две правки сошлись в одном шаге, и порознь обе половины зелены даже когда они
# спорят: выбор приёмника КОНЧАЕТСЯ меткой прошлого письма `LAST_AT`, а ветвь
# громкости с неё НАЧИНАЕТСЯ. Поэтому здесь они гоняются подряд, как в шаге:
# лента текущего приёмника → метка → строка, которую увидит читатель треда.
# Почта `$MAIL` — та же, что в разделе 9: открыт один приёмник `108`, у него
# письмо об отказе `Comms Derived` от 2026-09-03T16:39:00Z.
last_at_of_address() { # <корень почты> <слаг адреса> <ISO сейчас>
  local src
  src="$(notifier_mute_source "$1" "$2")"
  # Открытого приёмника нет — шаг ставит `LAST_AT=-` (ветвь `deliver` в
  # `notifier-watch.yml`): письмо поедет и откроет приёмник, глушить нечего.
  if [ -z "$src" ]; then printf -- '-\n'; return 0; fi
  notifier_mute_decide "$src" 'Comms Derived' "$3" | cut -d' ' -f2
}

check "метка берётся у ленты ТЕКУЩЕГО приёмника адреса" "2026-09-03T16:39:00Z" \
  "$(last_at_of_address "$MAIL" 'notifier-down' '2026-09-03T18:00:00Z')"
check "и ветвь громкости считает по ней — числом, а не отказом чтения" \
  '🔇 **Заглушено с прошлого письма (`2026-09-03T16:39:00Z`) отказов того же уведомителя: 1** — прогоны 33787502420. Правило — окно 900 с по имени уведомителя (`.github/scripts/notifier-mute.sh`).' \
  "$(muted_line ok "$RUNS_JSON" "$(last_at_of_address "$MAIL" 'notifier-down' '2026-09-03T18:00:00Z')" 33787757989)"
# У адреса без открытого приёмника метки нет — и строки громкости нет: считать
# заглушённое против ленты, которой ещё не существует, значило бы соврать числом.
check "у адреса без открытого приёмника метки нет" "-" \
  "$(last_at_of_address "$MAIL" 'нет-такого-адреса' '2026-09-03T18:00:00Z')"
check "и строки громкости при этом нет вовсе" "" \
  "$(muted_line ok "$RUNS_JSON" "$(last_at_of_address "$MAIL" 'нет-такого-адреса' '2026-09-03T18:00:00Z')" 33787757989)"

if [ "$FAILED" = 0 ]; then
  echo "правило глушения: все проверки прошли"
else
  echo "правило глушения: ЕСТЬ ОТКАЗЫ"
fi
exit "$FAILED"
